"""Generate docs/SITL.md from results/sitl_replay_{2,3,4}.json (numbers are not typed by hand)."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
runs = [json.loads((ROOT / "results" / f"sitl_replay_{n}.json").read_text()) for n in (2, 3, 4)]

L = ["# PX4 SITL replay (simulation only)", "",
     "Generated by `scripts/make_sitl_doc.py` from `results/sitl_replay_*.json` (`scripts/sitl_replay.py`). "
     "Do not edit by hand. Predictions P31 to P33 and their grading are in `docs/PREDICTIONS.md`.", "",
     "## What this is", "",
     "A small offline experiment. A planned and exactly verified show of 2, 3 and 4 drones is streamed as "
     "offboard position and velocity setpoints to PX4 running as a simulated multirotor (simulation in "
     "hardware, SIH, vehicle `sihsim_quadx`, PX4 default parameters, no tuning). The simulated vehicles' "
     "positions are logged and compared with the plan. It runs only in the cloud workspace. It never "
     "connects to a real vehicle or radio, and the planner and verifier are not changed by it.", "",
     "## Setup and measured limits of the workspace", "",
     "The workspace has " + str(runs[0]["machine_cores"]) + " cores and 8 GB of memory. Cloning PX4 with "
     "submodules (1.9 GB) took one to two minutes and `make px4_sitl_sih` about four minutes. Steps: clone "
     "`PX4/PX4-Autopilot` recursively and shallow, install the Python build dependencies (`empy` 3.3.4 "
     "needed its `em.py` copied into site packages because its wheel failed to build), run "
     "`make px4_sitl_sih`, start instances with `scripts/sitl_instances.sh start N`, then run "
     "`python scripts/sitl_replay.py N` (it needs the Python packages `pymavlink` and `psutil`, which are not dependencies of Sirb itself). Measured while replaying:", "",
     "| Vehicles | Mean CPU (cores) | Peak CPU (cores) | Max resident memory per instance (MB) | Wall time (s) |",
     "|---|---|---|---|---|"]
for d in runs:
    L.append(f"| {d['n_vehicles']} | {d['px4_cpu_cores_mean']:.2f} | {d['px4_cpu_cores_max']:.2f} | "
             f"{d['px4_rss_mb_max_per_instance']:.1f} | {d['wall_s']:.0f} |")
L += ["", "Only up to 4 vehicles were run. Nothing is claimed for larger counts.", "",
      "## Flown versus planned", "",
      f"Threshold {runs[0]['d_min_m']} m. Planned separation is the exact verifier value for the plan; "
      "flown separation is computed on the logged paths resampled at "
      f"{runs[0]['rate_hz']:.0f} Hz. One run per vehicle count; PX4 runs in real time so runs are not "
      "repeatable to the last digit.", "",
      "| Vehicles | Planned min separation (m) | Flown min separation (m) | Mean tracking error (m) | 95th percentile (m) | Max (m) |",
      "|---|---|---|---|---|---|"]
for d in runs:
    te = d["tracking_error_m"]
    L.append(f"| {d['n_vehicles']} | {d['planned_min_separation_exact_m']:.2f} | "
             f"{d['flown_min_separation_m']:.2f} | {te['mean']:.2f} | {te['p95']:.2f} | {te['max']:.2f} |")
L += ["", "## How to read it", "",
      "With default controller parameters the simulated vehicles do not follow the plan closely: the plan "
      "asks for speeds and accelerations that the default position controller does not deliver, so the "
      "tracking error reaches several metres and the flown minimum separation can fall far below the "
      "verified one, including below the threshold. This is what the verifier's wording already says: a "
      "pass applies to the planned polynomials, not to a flown path. It is not evidence about any real "
      "vehicle, since SIH uses a simple dynamics model with no wind, no GNSS error and no interaction "
      "between vehicles, and the comparison uses the wall clock to align the logs (an alignment error of "
      "50 ms at 10 m/s is 0.5 m). A tuned controller, or planning to the controller's actual limits, would "
      "change these numbers; that was not done.", ""]
(ROOT / "docs" / "SITL.md").write_text("\n".join(L))
